"use strict";(self.webpackChunkdocusaurus_website=self.webpackChunkdocusaurus_website||[]).push([["5081"],{86441(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"3.0","label":"Albatross (3.0 Beta)","banner":null,"badge":true,"noIndex":false,"className":"docs-version-3.0","isLast":false,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/albatross/","label":"Introduction","docId":"introduction","unlisted":false},{"type":"link","href":"/albatross/installation","label":"Installation","docId":"installation-guide","unlisted":false},{"type":"category","label":"General","items":[{"type":"link","href":"/albatross/general/features","label":"Albatross features","docId":"general/features","unlisted":false},{"type":"link","href":"/albatross/general/faq","label":"Albatross FAQ","docId":"general/faq","unlisted":false},{"type":"link","href":"/albatross/general/software-faq","label":"Software FAQ","docId":"general/software-faq","unlisted":false},{"type":"link","href":"/albatross/general/contributing","label":"Contributing","docId":"general/contributing","unlisted":false},{"type":"link","href":"/albatross/general/team","label":"Team","docId":"general/team","unlisted":false},{"type":"link","href":"/albatross/general/troubleshooting","label":"Troubleshooting","docId":"general/troubleshooting","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Hardware","items":[{"type":"link","href":"/albatross/first-link","label":"First-time setup","docId":"hardware/first-time-setup","unlisted":false},{"type":"category","label":"SBCs","items":[{"type":"category","label":"Raspberry","items":[{"type":"link","href":"/albatross/hardware/ochin","label":"Ochin CM4 Carrier","docId":"hardware/ochin","unlisted":false},{"type":"link","href":"/albatross/hardware/ochinv2","label":"ochin_CM4v2 Board","docId":"hardware/ochinv2","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/albatross/hardware/raspberry"},{"type":"link","href":"/albatross/hardware/X86","label":"x86 Ground","docId":"hardware/X86","unlisted":false},{"type":"link","href":"/albatross/hardware/radxa","label":"Radxa","docId":"hardware/radxa","unlisted":false},{"type":"link","href":"/albatross/hardware/custom-hardware","label":"OpenHD hardware","docId":"hardware/custom-hardware","unlisted":false},{"type":"category","label":"Discontinued Hardware","items":[{"type":"link","href":"/albatross/hardware/jetson","label":"jetson","docId":"hardware/jetson","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/albatross/hardware/discontinued"}],"collapsed":true,"collapsible":true,"href":"/albatross/hardware/sbcs"},{"type":"category","label":"Cameras","items":[{"type":"link","href":"/albatross/hardware/cameras/raspberry-cameras","label":"CSI Camera Modes on Raspberry Pi","docId":"hardware/cameras/raspberry-cameras","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/radxa-cameras","label":"Cameras","docId":"hardware/cameras/radxa-cameras","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/usb-camera","label":"USB Cameras","docId":"hardware/cameras/usb-camera","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/rpi-hdmi-to-csi","label":"RPI HDMI to CSI Adapter: Unofficial Usage and Quirks","docId":"hardware/cameras/rpi-hdmi-to-csi","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/hdmi-cameras-rpi","label":"HDMI Cameras","docId":"hardware/cameras/hdmi-cameras-rpi","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/ip-cameras","label":"IP cameras","docId":"hardware/cameras/ip-cameras","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/special-camera","label":"Special Use Case Cameras","docId":"hardware/cameras/special-camera","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/custom-cameras","label":"Cameras","docId":"hardware/cameras/custom-cameras","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/libcamera","label":"Libcamera","docId":"hardware/cameras/libcamera","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/raspicamsrc","label":"raspicamsrc","docId":"hardware/cameras/raspicamsrc","unlisted":false},{"type":"link","href":"/albatross/hardware/cameras/v4l2","label":"V4l2","docId":"hardware/cameras/v4l2","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/albatross/hardware/cameras"},{"type":"link","href":"/albatross/hardware/wifi-adapters","label":"WiFi Adapters","docId":"hardware/wifi-adapters","unlisted":false},{"type":"link","href":"/albatross/hardware/antennas","label":"Antennas","docId":"hardware/antennas","unlisted":false},{"type":"link","href":"/albatross/hardware/flightControllers","label":"Flight Controllers","docId":"hardware/flightControllers","unlisted":false},{"type":"link","href":"/albatross/hardware/wiring","label":"Wiring","docId":"hardware/wiring","unlisted":false},{"type":"link","href":"/albatross/hardware/displays","label":"Displays","docId":"hardware/displays","unlisted":false},{"type":"link","href":"/albatross/hardware/hardware.conf","label":"Hardware configuration","docId":"hardware/hardware.conf","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Software Setup","items":[{"type":"link","href":"/albatross/software-setup/inav","label":"INAV","docId":"software-setup/inav","unlisted":false},{"type":"link","href":"/albatross/software-setup/ardupilot","label":"Ardupilot","docId":"software-setup/ardupilot","unlisted":false},{"type":"link","href":"/albatross/software-setup/betaflight","label":"Betaflight","docId":"software-setup/betaflight","unlisted":false},{"type":"link","href":"/albatross/software-setup/px4","label":"PX4","docId":"software-setup/px4","unlisted":false},{"type":"link","href":"/albatross/software-setup/recording","label":"Recording","docId":"software-setup/recording","unlisted":false},{"type":"link","href":"/albatross/software-setup/tx-power","label":"TX Power","docId":"software-setup/tx-power","unlisted":false},{"type":"link","href":"/albatross/software-setup/mcs-via-rc","label":"MCS and bandwidth via RC","docId":"software-setup/mcs-via-rc","unlisted":false},{"type":"link","href":"/albatross/software-setup/joystick-rc","label":"Joystick RC control","docId":"software-setup/joystick-rc","unlisted":false},{"type":"link","href":"/albatross/software-setup/camera-settings","label":"Camera and video settings","docId":"software-setup/camera-settings","unlisted":false},{"type":"category","label":"Tethering","items":[{"type":"link","href":"/albatross/software-setup/ethernet-hotspot","label":"Ethernet networking","docId":"software-setup/ethernet-hotspot","unlisted":false},{"type":"link","href":"/albatross/software-setup/wifi-hotspot","label":"Wi-Fi hotspot","docId":"software-setup/wifi-hotspot","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/albatross/software-setup/tethering"},{"type":"link","href":"/albatross/software-setup/variable-bitrate","label":"Automatic video bitrate","docId":"software-setup/variable-bitrate","unlisted":false},{"type":"link","href":"/albatross/software-setup/telemetry-and-osd","label":"Telemetry and OSD","docId":"software-setup/telemetry-and-osd","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Advanced Setup","items":[{"type":"link","href":"/albatross/advanced-setup/air-recording","label":"Air recording","docId":"advanced-setup/air-recording","unlisted":false},{"type":"link","href":"/albatross/advanced-setup/dual-camera","label":"Dual Camera","docId":"advanced-setup/dual-camera","unlisted":false},{"type":"link","href":"/albatross/advanced-setup/ground-power-monitoring","label":"Ground power monitoring","docId":"advanced-setup/ground-power-monitoring","unlisted":false},{"type":"link","href":"/albatross/advanced-setup/Joystick","label":"Joystick Control","docId":"advanced-setup/Joystick","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Ground Station Software","items":[{"type":"link","href":"/albatross/qopenhd","label":"QOpenHD","docId":"ground-station-software/qopenhd","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/offline-maps","label":"Offline maps","docId":"ground-station-software/offline-maps","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/qopenhd-osd-backup","label":"QOpenHD Backup & Restore","docId":"ground-station-software/qopenhd-osd-backup","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/qgroundcontrol","label":"QGroundControl","docId":"ground-station-software/qgroundcontrol","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/mission-planner","label":"Mission Planner","docId":"ground-station-software/mission-planner","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/gstreamer","label":"Gstreamer","docId":"ground-station-software/gstreamer","unlisted":false},{"type":"link","href":"/albatross/ground-station-software/raspberrypi-camera-viewer","label":"RaspberryPi Camera Viewer","docId":"ground-station-software/raspberrypi-camera-viewer","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Developers Corner","items":[{"type":"link","href":"/albatross/developers/porting","label":"Running OpenHD and QOpenHD on \\"unsupported\\" Hardware","docId":"developers/porting","unlisted":false},{"type":"link","href":"/albatross/developers/radxa-commands","label":"radxa-commands","docId":"developers/radxa-commands","unlisted":false},{"type":"link","href":"/albatross/developers/wifi-adresses","label":"wifi-adresses","docId":"developers/wifi-adresses","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"advanced-setup/air-recording":{"id":"advanced-setup/air-recording","title":"Air recording","description":"1. Open Manage Air Storage if your build offers it. Select a recording destination with enough free space. Formatting, preparing, or resizing storage can change the partition layout and may erase data. Back up first.","sidebar":"tutorialSidebar"},"advanced-setup/dual-camera":{"id":"advanced-setup/dual-camera","title":"Dual Camera","description":"Dual camera setup process","sidebar":"tutorialSidebar"},"advanced-setup/ground-power-monitoring":{"id":"advanced-setup/ground-power-monitoring","title":"Ground power monitoring","description":"A supported Ground image can report supply voltage and current from an INA219 sensor. QOpenHD can display the reading in the Ground status card and on the HUD.","sidebar":"tutorialSidebar"},"advanced-setup/Joystick":{"id":"advanced-setup/Joystick","title":"Joystick Control","description":"Use this page for physical joystick wiring. Verify the controller is recognized by Ground, then calibrate and map it using the joystick software guide.","sidebar":"tutorialSidebar"},"developers/porting":{"id":"developers/porting","title":"Running OpenHD and QOpenHD on \\"unsupported\\" Hardware","description":"Use the current OpenHD, SysUtils, and QOpenHD sources for the target build. Validate boot, camera capture, radio transport, and Ground decoding separately. Check the generated platform and settings catalogs when adding board support.","sidebar":"tutorialSidebar"},"developers/radxa-commands":{"id":"developers/radxa-commands","title":"radxa-commands","description":"Confirm the command applies to the exact Radxa image, OS base, and role. Check the running kernel and board model before using an image- or device-specific command.","sidebar":"tutorialSidebar"},"developers/wifi-adresses":{"id":"developers/wifi-adresses","title":"wifi-adresses","description":"Identify the live radio by chipset, interface, and hardware address before editing configuration. Interface names and driver binding can differ between images and between USB ports.","sidebar":"tutorialSidebar"},"general/contributing":{"id":"general/contributing","title":"Contributing","description":"Include the exact 3.0 image build and relevant component versions when submitting a change. For docs changes, edit the Albatross version and test the affected routes and links.","sidebar":"tutorialSidebar"},"general/faq":{"id":"general/faq","title":"Albatross FAQ","description":"Is there a 3.0 image for my hardware?","sidebar":"tutorialSidebar"},"general/features":{"id":"general/features","title":"Albatross features","description":"| Area | What to use |","sidebar":"tutorialSidebar"},"general/software-faq":{"id":"general/software-faq","title":"Software FAQ","description":"Where do initial settings come from?","sidebar":"tutorialSidebar"},"general/team":{"id":"general/team","title":"Team","description":"See the project\u2019s contributing and support pages for the current contact routes. The credits below recognize the people who built and maintained OpenHD.","sidebar":"tutorialSidebar"},"general/troubleshooting":{"id":"general/troubleshooting","title":"Troubleshooting","description":"Establish which path is failing","sidebar":"tutorialSidebar"},"ground-station-software/gstreamer":{"id":"ground-station-software/gstreamer","title":"Gstreamer","description":"Use an RTP caps declaration and depayloader that match the active stream codec. Verify the Ground forwarding destination and port. Use the examples below as H.264 starting points when that codec is selected.","sidebar":"tutorialSidebar"},"ground-station-software/mission-planner":{"id":"ground-station-software/mission-planner","title":"Mission Planner","description":"Verify MAVLink forwarding to Mission Planner first, then configure video independently. Use the Ground address and ports from your setup. The screenshots below show the client-side workflow.","sidebar":"tutorialSidebar"},"ground-station-software/offline-maps":{"id":"ground-station-software/offline-maps","title":"Offline maps","description":"QOpenHD and OpenHD Glide can read .glidemap map packages. Select OpenHD Offline as the map provider in QOpenHD. This provider serves tiles from installed map packages and needs coverage for the area and zoom you want to use.","sidebar":"tutorialSidebar"},"ground-station-software/qgroundcontrol":{"id":"ground-station-software/qgroundcontrol","title":"QGroundControl","description":"Connect QGroundControl to the Ground network before enabling forwarding. Verify a MAVLink heartbeat and set the video input to the codec and port forwarded by your build. Check that both streams work with QOpenHD open.","sidebar":"tutorialSidebar"},"ground-station-software/qopenhd":{"id":"ground-station-software/qopenhd","title":"QOpenHD","description":"Check and configure a link","sidebar":"tutorialSidebar"},"ground-station-software/qopenhd-osd-backup":{"id":"ground-station-software/qopenhd-osd-backup","title":"QOpenHD Backup & Restore","description":"Open QOpenHD settings and select Backup & Restore.","sidebar":"tutorialSidebar"},"ground-station-software/raspberrypi-camera-viewer":{"id":"ground-station-software/raspberrypi-camera-viewer","title":"RaspberryPi Camera Viewer","description":"Use this as a third-party receiver only after confirming it can decode the codec forwarded by Ground. Use QOpenHD for configuring the OpenHD link and viewing its status.","sidebar":"tutorialSidebar"},"hardware/antennas":{"id":"hardware/antennas","title":"Antennas","description":"Fit antennas before powering the radios. Match the band, connector, and polarization on both ends, and bench-test the chosen arrangement using link statistics before changing power or bandwidth.","sidebar":"tutorialSidebar"},"hardware/cameras":{"id":"hardware/cameras","title":"Cameras","description":"Choose a camera that the image for your Air board supports. Start with one camera at a conservative resolution and frame rate. In QOpenHD, confirm Air is connected before troubleshooting the video stream.","sidebar":"tutorialSidebar"},"hardware/cameras/custom-cameras":{"id":"hardware/cameras/custom-cameras","title":"Cameras","description":"Use the Air board\u2019s driver and camera mode inventory for the selected build. If autodetection fails, identify the sensor and board revision before trying a manual camera setting. Include both details when reporting a missing camera.","sidebar":"tutorialSidebar"},"hardware/cameras/hdmi-cameras-rpi":{"id":"hardware/cameras/hdmi-cameras-rpi","title":"HDMI Cameras","description":"Check that the image exposes the HDMI bridge as a capture device before applying legacy overlays. Confirm that the source, adapter, and Air encoder agree on resolution and frame rate.","sidebar":"tutorialSidebar"},"hardware/cameras/ip-cameras":{"id":"hardware/cameras/ip-cameras","title":"IP cameras","description":"1. Connect the camera to Air\u2019s local network and verify its address and video stream on that network.","sidebar":"tutorialSidebar"},"hardware/cameras/libcamera":{"id":"hardware/cameras/libcamera","title":"Libcamera","description":"Use the libcamera stack that ships with the selected Pi image. Verify the sensor is detected and choose a supported mode before changing encoder settings in QOpenHD.","sidebar":"tutorialSidebar"},"hardware/cameras/radxa-cameras":{"id":"hardware/cameras/radxa-cameras","title":"Cameras","description":"Check the sensor, Radxa board, and camera connector together. Camera support requires a driver and matching board configuration in the Air image. Pick a supported format in QOpenHD after detection.","sidebar":"tutorialSidebar"},"hardware/cameras/raspberry-cameras":{"id":"hardware/cameras/raspberry-cameras","title":"CSI Camera Modes on Raspberry Pi","description":"Check the sensor and available modes on the selected Albatross image. Start with a single connected sensor and use the backend exposed by that image. Older MMAL procedures apply only to images that ship the legacy stack.","sidebar":"tutorialSidebar"},"hardware/cameras/raspicamsrc":{"id":"hardware/cameras/raspicamsrc","title":"raspicamsrc","description":"This is a legacy Raspberry Pi camera backend. Use it only if your image explicitly ships it. For current Pi images, check the libcamera and V4L2 guides for the backend provided by your build.","sidebar":"tutorialSidebar"},"hardware/cameras/rpi-hdmi-to-csi":{"id":"hardware/cameras/rpi-hdmi-to-csi","title":"RPI HDMI to CSI Adapter: Unofficial Usage and Quirks","description":"Match the bridge to the Pi CSI connector and to the driver included in the selected Air image. Set the HDMI source to a mode the bridge reports as supported, then verify input and QOpenHD display on the bench.","sidebar":"tutorialSidebar"},"hardware/cameras/special-camera":{"id":"hardware/cameras/special-camera","title":"Special Use Case Cameras","description":"Verify the camera\u2019s output type first. For a thermal or global-shutter device, check both driver support on the chosen Air image and the format exposed by the vendor. Confirm a stable picture before enabling a second stream.","sidebar":"tutorialSidebar"},"hardware/cameras/usb-camera":{"id":"hardware/cameras/usb-camera","title":"USB Cameras","description":"Attach the camera before boot and verify that the Air image detects it as a V4L2 device. Check the modes the device advertises, then test a single stream before changing the camera\u2019s encoding settings.","sidebar":"tutorialSidebar"},"hardware/cameras/v4l2":{"id":"hardware/cameras/v4l2","title":"V4l2","description":"Check which capture device corresponds to your camera and inspect the modes it advertises. Configure one supported resolution, frame rate, and pixel format, then check Air video and Ground decoding separately.","sidebar":"tutorialSidebar"},"hardware/custom-hardware":{"id":"hardware/custom-hardware","title":"OpenHD hardware","description":"Select the exact X20 or X21 variant in ImageWriter. Some OpenHD hardware images already have a fixed Air role. Check the board revision, camera and intended recovery mode before selecting an artifact.","sidebar":"tutorialSidebar"},"hardware/discontinued":{"id":"hardware/discontinued","title":"Discontinued Hardware","description":"Treat the list below as hardware history. Before reusing a discontinued platform, confirm there is a current image for it and a matching camera and radio configuration.","sidebar":"tutorialSidebar"},"hardware/displays":{"id":"hardware/displays","title":"Displays","description":"Check the Ground build and connection type first. Local QOpenHD and a remote QOpenHD client have different display and networking requirements. Verify decode and display at your normal operating resolution.","sidebar":"tutorialSidebar"},"hardware/first-time-setup":{"id":"hardware/first-time-setup","title":"First-time setup","description":"Assemble Air and Ground","sidebar":"tutorialSidebar"},"hardware/flightControllers":{"id":"hardware/flightControllers","title":"Flight Controllers","description":"Use a spare compatible UART and match its protocol and baud rate with OpenHD Air. Verify the controller heartbeat and the telemetry you need in QOpenHD before enabling an RC input path.","sidebar":"tutorialSidebar"},"hardware/hardware.conf":{"id":"hardware/hardware.conf","title":"Hardware configuration","description":"Use ImageWriter to seed the role, hardware selection, and initial parameter defaults offered by the selected image. Then use QOpenHD or the device\u2019s configuration interface to inspect the live controls.","sidebar":"tutorialSidebar"},"hardware/jetson":{"id":"hardware/jetson","title":"jetson","description":"The current Albatross image workflow has no Jetson target. The historical instructions below apply to older releases. Use a board with a matching 3.0 image when setting up Albatross.","sidebar":"tutorialSidebar"},"hardware/ochin":{"id":"hardware/ochin","title":"Ochin CM4 Carrier","description":"Select the image for the underlying CM4 and the flashing method for its storage. An eMMC CM4 uses the carrier\u2019s USB boot procedure. An SD-based setup uses removable media. Confirm the CSI cable and orientation against the carrier revision.","sidebar":"tutorialSidebar"},"hardware/ochinv2":{"id":"hardware/ochinv2","title":"ochin_CM4v2 Board","description":"Confirm CM4 storage, camera port, and carrier revision before preparing the image. Keep the carrier\u2019s power and boot-mode instructions beside you when using USB recovery.","sidebar":"tutorialSidebar"},"hardware/radxa":{"id":"hardware/radxa","title":"Radxa","description":"The Albatross builder lists separate ROCK 5A, ROCK 5B, ROCK 3A, and Radxa Zero 3W targets. Choose the matching artifact. Images for different boards carry different boot configuration and drivers.","sidebar":"tutorialSidebar"},"hardware/raspberry":{"id":"hardware/raspberry","title":"Raspberry Pi","description":"Select the exact Raspberry Pi board and role in ImageWriter. Check the camera and radio against the image before writing it. The Raspberry Pi build pipeline produces a shared Bullseye image artifact. Confirm the board options exposed for the build you select.","sidebar":"tutorialSidebar"},"hardware/sbcs":{"id":"hardware/sbcs","title":"Boards and images","description":"Choose an exact board, role, and target storage in ImageWriter. Board entries in a configuration catalog and downloadable images are separate.","sidebar":"tutorialSidebar"},"hardware/wifi-adapters":{"id":"hardware/wifi-adapters","title":"WiFi Adapters","description":"Radio and driver compatibility for OpenHD Albatross","sidebar":"tutorialSidebar"},"hardware/wiring":{"id":"hardware/wiring","title":"Wiring","description":"Check pinout and supply requirements for the exact carrier, camera, and radio revision. On the bench, bring up power and video before attaching the flight controller, then verify telemetry as a separate step.","sidebar":"tutorialSidebar"},"hardware/X86":{"id":"hardware/X86","title":"x86 Ground","description":"Albatross ImageBuilder has separate x86 minimal and x86 Noble targets. Check which Ground client and desktop the selected image includes. Use the storage and boot method provided for that image.","sidebar":"tutorialSidebar"},"improvements-hardware-configurator":{"id":"improvements-hardware-configurator","title":"Hardware Configurator - Datenverbesserungen","description":"Die aktuellen Plattform-IDs stammen aus dem OpenHD-Plattformkatalog. Ger\xe4teauswahl, tats\xe4chlich verf\xfcgbare Images und unterst\xfctzte Funktionen m\xfcssen getrennt gepr\xfcft werden."},"installation-guide":{"id":"installation-guide","title":"Installation and migration","description":"Choose and write OpenHD 3.0 Albatross images using ImageWriter.","sidebar":"tutorialSidebar"},"introduction":{"id":"introduction","title":"OpenHD 3.0 Albatross","description":"Start with the OpenHD 3.0 Albatross manual for Air, Ground, and QOpenHD.","sidebar":"tutorialSidebar"},"software-setup/ardupilot":{"id":"software-setup/ardupilot","title":"Ardupilot","description":"Configure the ArduPilot SERIAL port for MAVLink and match the baud rate on OpenHD Air. Once telemetry is connected, verify the specific stream rates and RC channel reporting you need on the bench.","sidebar":"tutorialSidebar"},"software-setup/betaflight":{"id":"software-setup/betaflight","title":"Betaflight","description":"Check the telemetry protocol and available UARTs in your Betaflight version, then verify which fields arrive in QOpenHD. Keep MSP display output and MAVLink telemetry distinct when configuring ports.","sidebar":"tutorialSidebar"},"software-setup/camera-settings":{"id":"software-setup/camera-settings","title":"Camera and video settings","description":"In QOpenHD, open the sidebar and choose Video to set the stream format, codec, rotation, or bitrate when available. Start with a format supported by the camera driver and Ground decoder. A change may restart the Air stream briefly.","sidebar":"tutorialSidebar"},"software-setup/ethernet-hotspot":{"id":"software-setup/ethernet-hotspot","title":"Ethernet networking","description":"Ground to a client","sidebar":"tutorialSidebar"},"software-setup/inav":{"id":"software-setup/inav","title":"INAV","description":"Use a matching UART protocol and baud rate on Air and INAV. Verify the flight controller heartbeat and a live telemetry field in QOpenHD. If you need RC over OpenHD, validate its input path separately from telemetry.","sidebar":"tutorialSidebar"},"software-setup/joystick-rc":{"id":"software-setup/joystick-rc","title":"Joystick RC control","description":"Connect the joystick to the QOpenHD device. For a USB radio transmitter, select its joystick mode. The Air unit and flight controller need a working control path before joystick input can reach the model.","sidebar":"tutorialSidebar"},"software-setup/mcs-via-rc":{"id":"software-setup/mcs-via-rc","title":"MCS and bandwidth via RC","description":"On supported Wi-Fi broadcast builds, OpenHD Air can map a flight-controller RC channel to a link setting. MCS changes the radio data rate. Bandwidth changes the channel width and requires both units to stay synchronized.","sidebar":"tutorialSidebar"},"software-setup/px4":{"id":"software-setup/px4","title":"PX4","description":"Configure a PX4 MAVLink instance on the chosen UART and match the Air baud rate. Check heartbeat and live data in QOpenHD before configuring a Ground-side MAVLink client.","sidebar":"tutorialSidebar"},"software-setup/recording":{"id":"software-setup/recording","title":"Recording","description":"Air recording saves the encoded video at the camera side, where it is unaffected by loss over the radio link. Screen recording saves what your Ground device displays, including its HUD if visible, and reflects any reception interruptions.","sidebar":"tutorialSidebar"},"software-setup/telemetry-and-osd":{"id":"software-setup/telemetry-and-osd","title":"Telemetry and OSD","description":"Bring up flight-controller telemetry","sidebar":"tutorialSidebar"},"software-setup/tethering":{"id":"software-setup/tethering","title":"Tethering to Ground","description":"Connect a QOpenHD or MAVLink client to the Ground unit over an IP network. This connection is separate from the link that carries video and telemetry between Air and Ground.","sidebar":"tutorialSidebar"},"software-setup/tx-power":{"id":"software-setup/tx-power","title":"TX Power","description":"Change transmit power in the active link\u2019s settings. Hardware capabilities and units depend on the adapter and driver. Recheck displayed power and link health after changing antenna, band, or radio.","sidebar":"tutorialSidebar"},"software-setup/variable-bitrate":{"id":"software-setup/variable-bitrate","title":"Automatic video bitrate","description":"VAUTOBITRATE enables automatic video bitrate allocation across the links carrying video. When disabled, OpenHD restores the saved per-camera manual bitrates.","sidebar":"tutorialSidebar"},"software-setup/wifi-hotspot":{"id":"software-setup/wifi-hotspot","title":"Wi-Fi hotspot","description":"Enable the OpenHD hotspot only on a supported interface. Open the connected unit\u2019s network settings and select the hotspot mode and, where exposed, its interface. Check which interface is carrying the primary OpenHD link before selecting one.","sidebar":"tutorialSidebar"},"support":{"id":"support","title":"Support","description":"When asking for help, include the exact Albatross image name, Air and Ground models, radios, camera, and QOpenHD version."}}}}')}}]);